import{_ as t,o as e,c as l,ai as i}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Agent 面试 · Tool Calling","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/tool-calling-interview.md","filePath":"guide/agent/tool-calling-interview.md"}'),n={name:"guide/agent/tool-calling-interview.md"};function r(d,a,s,o,h,c){return e(),l("div",null,[...a[0]||(a[0]=[i(`<h1 id="agent-面试-·-tool-calling" tabindex="-1">Agent 面试 · Tool Calling <a class="header-anchor" href="#agent-面试-·-tool-calling" aria-label="Permalink to “Agent 面试 · Tool Calling”">​</a></h1><blockquote><p>工具调用是 Agent 的「手脚」。面试重点：模型出意图，<strong>你的系统执行</strong>。</p></blockquote><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>Tool Calling / Function Calling 是什么？</li><li>和「让模型输出 JSON 再自己解析」有什么区别？</li><li>怎么设计一个工具（入参、出参、错误）？</li><li>并行调多个工具可以吗？注意什么？</li><li>工具太多了模型选错怎么办？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-是什么" tabindex="-1">1）是什么 <a class="header-anchor" href="#_1-是什么" aria-label="Permalink to “1）是什么”">​</a></h3><p>模型不「假装调了接口」，而是按约定产出：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>工具名 + 参数（结构化）</span></span>
<span class="line"><span>  → 后端真实执行</span></span>
<span class="line"><span>  → 结果（成功/失败信息）写回上下文</span></span>
<span class="line"><span>  → 模型继续推理或结束</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>你方负责：<strong>鉴权、校验、超时、幂等、审计</strong>。</p><h3 id="_2-对比自己解析-json" tabindex="-1">2）对比自己解析 JSON <a class="header-anchor" href="#_2-对比自己解析-json" aria-label="Permalink to “2）对比自己解析 JSON”">​</a></h3><table tabindex="0"><thead><tr><th>做法</th><th>优点</th><th>风险</th></tr></thead><tbody><tr><td>自然语言里「我已经查询了」</td><td>演示快</td><td>不可信</td></tr><tr><td>正则 / 手写 JSON 解析</td><td>灵活</td><td>格式一漂就挂</td></tr><tr><td>官方 Tool Calling + Schema</td><td>与模型对齐、可校验</td><td>依赖厂商协议</td></tr></tbody></table><p>生产建议：<strong>Schema 校验失败就重试或降级</strong>，不要硬跑。</p><h3 id="_3-工具设计清单-面试可照念" tabindex="-1">3）工具设计清单（面试可照念） <a class="header-anchor" href="#_3-工具设计清单-面试可照念" aria-label="Permalink to “3）工具设计清单（面试可照念）”">​</a></h3><p>每个工具至少讲清：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>名称与描述</td><td>给模型看，描述要「何时用」</td></tr><tr><td>入参 Schema</td><td>类型、必填、枚举、范围</td></tr><tr><td>出参</td><td>成功结构；失败要有 <code>code/message</code>，别只抛栈</td></tr><tr><td>副作用</td><td>只读 vs 写入；写入是否要确认</td></tr><tr><td>超时与重试</td><td>多久算失败；能否幂等重试</td></tr><tr><td>权限</td><td>谁能调；是否按租户隔离</td></tr></tbody></table><p>示例（口述）：「查订单工具只读；取消订单工具要用户 id + 订单 id，且做幂等键，防止重复取消。」</p><h3 id="_4-并行工具" tabindex="-1">4）并行工具 <a class="header-anchor" href="#_4-并行工具" aria-label="Permalink to “4）并行工具”">​</a></h3><p>可以：互不依赖的只读查询可并行，降低延迟。<br> 注意：有先后依赖（先查库存再下单）必须串行；并行写入要防冲突。</p><h3 id="_5-工具太多选错" tabindex="-1">5）工具太多选错 <a class="header-anchor" href="#_5-工具太多选错" aria-label="Permalink to “5）工具太多选错”">​</a></h3><ul><li>按场景拆子集（不同 Agent 不同工具包）</li><li>描述写清「不要用于…」</li><li>危险操作二次确认或人工审批</li><li>监控「选错工具率」，用日志反推改描述</li></ul><hr><h2 id="追问预备" tabindex="-1">追问预备 <a class="header-anchor" href="#追问预备" aria-label="Permalink to “追问预备”">​</a></h2><ul><li>「流式输出时怎么插工具？」→ 先收齐 tool_call，再执行，再继续生成。</li><li>「和 MCP 关系？」→ MCP 偏「工具/资源怎么标准暴露」；Tool Calling 是模型侧调用形态。知道分层即可。</li></ul>`,25)])])}const g=t(n,[["render",r]]);export{b as __pageData,g as default};
